import heapq
def solution(grid):
    n = len(grid)
    visited = {(0, 0)}
    h = [(grid[0][0], 0, 0)]
    ans = 0
    while h:
        val, r, c = heapq.heappop(h)
        ans = max(ans, val)
        if r == n - 1 and c == n - 1:
            return ans
        for nr, nc in [(r+1, c), (r-1, c), (r, c+1), (r, c-1)]:
            if 0 <= nr < n and 0 <= nc < n and (nr, nc) not in visited:
                visited.add((nr, nc))
                heapq.heappush(h, (grid[nr][nc], nr, nc))
    return ans
